// Generated by scripts/emit-typedefs.ts from schema/*.graphql. Do not edit.
export const typeDefs = "# _root.graphql\n# Root types. Every other file extends them, one domain per file (AGENTS.md §16).\ntype Query\ntype Mutation\n\n\"An ISO 8601 date-time, in UTC.\"\nscalar DateTime\n\n\"\"\"\nA rich-text document (Tiptap JSON, schema version 1). Validated by the API on every write; only known node\nand mark types are accepted, and links must be http(s) or mailto.\n\"\"\"\nscalar RichText\n\n\"For cursor pagination: pass endCursor as `after` to get the next page.\"\ntype PageInfo {\n  endCursor: String\n  hasNextPage: Boolean!\n}\n\n\"CEFR levels. An editorial estimate of a lesson's difficulty, not a guarantee of a learner's level.\"\nenum CefrLevel {\n  A1\n  A2\n  B1\n  B2\n  C1\n  C2\n}\n\n# assessment.graphql\n\"\"\"\nExercises as editors write them: a list of sets, each {title, instructions?, questions: [...]}, where a question is\n{type, points?, prompt, options? (single choice), grading, explanation?}. Validated in full by the API; see\napps/api/src/modules/assessment/schemas.ts for the exact shape of each question type. Editorial only.\n\"\"\"\nscalar ExercisePayload\n\nenum QuestionType {\n  SINGLE_CHOICE\n  TRUE_FALSE_NOT_GIVEN\n  GAP_FILL\n}\n\nenum Judgement {\n  TRUE\n  FALSE\n  NOT_GIVEN\n}\n\n\"A question as the learner sees it. Answers are never part of it: they come back from gradePractice.\"\ninterface Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n}\n\ntype QuestionOption {\n  id: ID!\n  content: String!\n}\n\ntype SingleChoiceQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  stem: String!\n  options: [QuestionOption!]!\n}\n\ntype TrueFalseNotGivenQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  statement: String!\n}\n\ntype TextSegment {\n  text: String!\n}\n\ntype GapSegment {\n  gapId: String!\n}\n\nunion GapFillSegment = TextSegment | GapSegment\n\ntype GapFillQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  segments: [GapFillSegment!]!\n}\n\ntype ExerciseSet {\n  id: ID!\n  title: String!\n  instructions: String\n  questions: [Question!]!\n}\n\ninput GapAnswerInput {\n  gapId: String!\n  text: String!\n}\n\n\"One answer: optionId for single choice, judgement for true/false/not given, gaps for gap fill.\"\ninput PracticeAnswerInput {\n  questionId: ID!\n  optionId: ID\n  judgement: Judgement\n  gaps: [GapAnswerInput!]\n}\n\ninput GradePracticeInput {\n  exerciseSetId: ID!\n  \"At most 100.\"\n  answers: [PracticeAnswerInput!]!\n}\n\ntype ChoiceAnswer {\n  optionId: ID!\n}\n\ntype JudgementAnswer {\n  judgement: Judgement!\n}\n\ntype GapAnswer {\n  gapId: String!\n  \"The first accepted answer.\"\n  text: String!\n}\n\ntype GapsAnswer {\n  gaps: [GapAnswer!]!\n}\n\nunion CorrectAnswer = ChoiceAnswer | JudgementAnswer | GapsAnswer\n\ntype QuestionResult {\n  questionId: ID!\n  correct: Boolean!\n  awardedPoints: Int!\n  maxPoints: Int!\n  explanation: String\n  correctAnswer: CorrectAnswer!\n}\n\ntype PracticeResult {\n  exerciseSetId: ID!\n  score: Int!\n  maxScore: Int!\n  questions: [QuestionResult!]!\n}\n\nextend type Query {\n  \"A published exercise set on this site.\"\n  exerciseSet(id: ID!): ExerciseSet\n}\n\nextend type Mutation {\n  \"Grades answers on the server. Nothing is stored: practice is anonymous in the MVP.\"\n  gradePractice(input: GradePracticeInput!): PracticeResult!\n}\n\n# health.graphql\n\"Whether a part of the system is working.\"\nenum HealthStatus {\n  OK\n  DOWN\n}\n\n\"The API's own view of its health. Public: it reveals no hostnames, versions of dependencies or errors.\"\ntype Health {\n  status: HealthStatus!\n  database: HealthStatus!\n}\n\nextend type Query {\n  health: Health!\n}\n\n# identity.graphql\nenum SiteRole {\n  OWNER\n  ADMIN\n  EDITOR\n  REVIEWER\n  VIEWER\n}\n\ntype Site {\n  id: ID!\n  domain: String!\n  name: String!\n  defaultLocale: String!\n}\n\ntype Membership {\n  site: Site!\n  role: SiteRole!\n}\n\n\"The signed-in editor. Learners have no accounts until a later phase.\"\ntype Viewer {\n  id: ID!\n  email: String!\n  name: String\n  memberships: [Membership!]!\n}\n\nextend type Query {\n  \"Who is signed in (from the request's session token), or null.\"\n  viewer: Viewer\n}\n\n# lexicon.graphql\nenum LexicalEntryKind {\n  WORD\n  PHRASE\n  COLLOCATION\n  IDIOM\n  PHRASAL_VERB\n  \"A grammar or sentence pattern, e.g. \\\"If I were you, I'd + verb\\\". Learners add it whole.\"\n  SENTENCE_PATTERN\n}\n\n\"The meaning in another language.\"\ntype Translation {\n  \"BCP 47 language, e.g. vi or pt-BR.\"\n  locale: String!\n  text: String!\n}\n\ninput TranslationInput {\n  locale: String!\n  text: String!\n}\n\n\"Where a vocabulary item appears in a text: a span of one block, and the sentence around it.\"\ntype TextOccurrence {\n  blockId: String!\n  \"Unicode code-point offsets into the block's text.\"\n  start: Int!\n  end: Int!\n  text: String!\n  sentence: String!\n}\n\n\"\"\"\nA word or structure a text links to, as learners choose it: the exact sense revision the text pinned, whether the\neditor marked it a key word, and every place it appears (a split pattern has several).\n\"\"\"\ntype VocabularyItem {\n  sense: LexicalSense!\n  isKey: Boolean!\n  occurrences: [TextOccurrence!]!\n}\n\ntype LexicalExample {\n  sentence: String!\n  explanation: String\n}\n\ntype Pronunciation {\n  \"BCP 47 accent label, e.g. en-GB or en-US.\"\n  accent: String!\n  ipa: String!\n}\n\n\"One meaning of a headword, as one exact revision.\"\ntype LexicalSense {\n  id: ID!\n  senseKey: String!\n  partOfSpeech: String!\n  revisionId: ID!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  examples: [LexicalExample!]!\n  pronunciations: [Pronunciation!]!\n  translations: [Translation!]!\n  entry: LexicalEntry!\n}\n\ntype LexicalEntry {\n  id: ID!\n  displayForm: String!\n  kind: LexicalEntryKind!\n  language: String!\n  \"Published senses only.\"\n  senses: [LexicalSense!]!\n}\n\nextend type Query {\n  \"Exact and fuzzy headword lookup. Only entries with a published sense. `first` is at most 50.\"\n  lexicalSearch(query: String!, first: Int! = 20): [LexicalEntry!]!\n  lexicalEntryById(id: ID!): LexicalEntry\n}\n\n# --- Editorial\n\ntype SenseRevision {\n  id: ID!\n  revisionNo: Int!\n  status: RevisionStatus!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  lockVersion: Int!\n  examples: [LexicalExample!]!\n  pronunciations: [Pronunciation!]!\n  translations: [Translation!]!\n  publishedAt: DateTime\n}\n\ntype EditorialSense {\n  id: ID!\n  site: Site!\n  senseKey: String!\n  partOfSpeech: String!\n  entry: LexicalEntry!\n  draft: SenseRevision\n  published: SenseRevision\n}\n\ninput LexicalExampleInput {\n  sentence: String!\n  explanation: String\n}\n\ninput PronunciationInput {\n  accent: String!\n  ipa: String!\n}\n\n\"\"\"\nCreates a sense (and its entry, given headword and kind), or edits a sense's draft. Editing a sense with no\ndraft starts a new draft revision; the published one is never changed.\n\"\"\"\ninput ManageLexicalSenseInput {\n  siteId: ID!\n  \"An existing sense to edit. Omit to create one.\"\n  senseId: ID\n  \"For a new sense: its entry, or headword + kind to create one.\"\n  entryId: ID\n  headword: String\n  kind: LexicalEntryKind\n  partOfSpeech: String!\n  senseKey: String!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  examples: [LexicalExampleInput!]! = []\n  pronunciations: [PronunciationInput!]! = []\n  translations: [TranslationInput!]! = []\n  \"Required when editing an existing draft.\"\n  lockVersion: Int\n}\n\nextend type Query {\n  \"Editorial: the site's word bank, drafts included, optionally filtered by headword (at most 200).\"\n  editorialSenses(siteId: ID!, query: String, first: Int! = 100): [EditorialSense!]!\n  \"Editorial: one sense with its draft and published revisions.\"\n  editorialSense(id: ID!): EditorialSense\n}\n\nextend type Mutation {\n  manageLexicalSense(input: ManageLexicalSenseInput!): EditorialSense!\n  publishLexicalSense(senseId: ID!, lockVersion: Int!): EditorialSense!\n}\n\n# resources.graphql\nenum ResourceKind {\n  READING\n  LISTENING\n  LEXICAL_COLLECTION\n  ARTICLE\n}\n\nenum RevisionStatus {\n  DRAFT\n  IN_REVIEW\n  PUBLISHED\n  SUPERSEDED\n}\n\ntype Topic {\n  id: ID!\n  slug: String!\n  name: String!\n  description: String\n}\n\ntype ExamLabel {\n  id: ID!\n  code: String!\n  name: String!\n}\n\n\"A published lesson or article, as learners see it. Always one exact, frozen revision.\"\ninterface Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ntype ReadingResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n  \"The word senses the text links to (its `lexical` marks), at the exact revisions it pinned.\"\n  vocabulary: [LexicalSense!]!\n  \"The same links as learners choose them: one item per word or structure, with key flags and sentences.\"\n  vocabularyItems: [VocabularyItem!]!\n  wordCount: Int!\n  \"At about 200 words a minute.\"\n  estimatedReadingSeconds: Int!\n}\n\ntype ListeningResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  \"The transcript. Audio tracks and timings arrive in Phase 3.\"\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ntype LexicalCollectionResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n  \"The words, pinned to the exact sense revisions chosen when the collection was published.\"\n  items: [LexicalSense!]!\n}\n\ntype ArticleResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ninput ResourceFilter {\n  kind: ResourceKind\n  cefrLevel: CefrLevel\n  topicSlug: String\n  \"Defaults to the site's default locale.\"\n  locale: String\n  \"Full-text search in titles, summaries and text.\"\n  search: String\n}\n\ntype ResourceConnection {\n  nodes: [Resource!]!\n  pageInfo: PageInfo!\n}\n\nextend type Query {\n  \"Published resources on this site, newest first. `first` is at most 50.\"\n  publishedResources(filter: ResourceFilter, first: Int! = 20, after: String): ResourceConnection!\n  resourceBySlug(kind: ResourceKind!, slug: String!, locale: String): Resource\n  topics: [Topic!]!\n\n  \"Editorial: a resource with its draft and published revisions. Members of its site only.\"\n  editorialResource(id: ID!): EditorialResource\n  \"Editorial: a site's resources, newest first (at most 100).\"\n  editorialResources(siteId: ID!, first: Int! = 50): [EditorialResource!]!\n}\n\n# --- Editorial\n\ntype Revision {\n  id: ID!\n  revisionNo: Int!\n  status: RevisionStatus!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  topics: [Topic!]!\n  \"The linked word senses, as in the text.\"\n  vocabulary: [LexicalSense!]!\n  vocabularyItems: [VocabularyItem!]!\n  \"The exercises, answer keys included, in the shape saveExerciseSets takes. Editors only.\"\n  exercises: ExercisePayload!\n  \"Pass this back when you change the revision; a mismatch means someone else changed it first.\"\n  lockVersion: Int!\n  createdAt: DateTime!\n  updatedAt: DateTime!\n  submittedAt: DateTime\n  publishedAt: DateTime\n}\n\ntype EditorialLocalization {\n  id: ID!\n  locale: String!\n  slug: String!\n  draft: Revision\n  published: Revision\n}\n\ntype EditorialResource {\n  id: ID!\n  kind: ResourceKind!\n  site: Site!\n  createdAt: DateTime!\n  archivedAt: DateTime\n  localizations: [EditorialLocalization!]!\n}\n\ninput CreateResourceInput {\n  siteId: ID!\n  kind: ResourceKind!\n  locale: String! = \"en\"\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText\n  topicSlugs: [String!]\n}\n\ninput UpdateDraftInput {\n  localizationId: ID!\n  lockVersion: Int!\n  title: String\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText\n  \"Replaces the draft's topics.\"\n  topicSlugs: [String!]\n}\n\nextend type Mutation {\n  \"Editors: a new resource with its first draft.\"\n  createResource(input: CreateResourceInput!): EditorialResource!\n  \"Editors: a new draft copied from the published revision (exercises included).\"\n  startDraft(localizationId: ID!): EditorialResource!\n  updateDraft(input: UpdateDraftInput!): EditorialResource!\n  \"Editors: hand the draft to a reviewer.\"\n  submitForReview(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Reviewers: send it back to the editor.\"\n  returnToDraft(localizationId: ID!, lockVersion: Int!, note: String): EditorialResource!\n  \"Reviewers: publish the reviewed draft. The previous published revision is superseded, never changed.\"\n  publishResource(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Editors: replace the draft's exercises. Validated as a whole.\"\n  saveExerciseSets(localizationId: ID!, lockVersion: Int!, sets: ExercisePayload!): EditorialResource!\n  \"Admins and owners: publish a draft straight away, without the review queue. Recorded in the audit log.\"\n  publishNow(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Admins: take the resource off the site. Its revisions are kept.\"\n  archiveResource(resourceId: ID!): EditorialResource!\n}\n";
